// Read the KBC export (CSV with ; and decimal commas) into clean bank lines.
const item = $input.first();
const key = Object.keys(item.binary ?? {})[0];
if (!key) throw new Error('No file was uploaded');
const fileName = item.binary[key].fileName ?? 'bank-export.csv';
const text = (await this.helpers.getBinaryDataBuffer(0, key)).toString('utf8').replace(/^﻿/, '');
const lines = text.split(/\r?\n/).filter((l) => l.trim());

const header = lines[0].split(';').map((h) => h.trim().toLowerCase());
const col = (name) => header.indexOf(name);
for (const name of ['datum', 'bedrag', 'naam tegenpartij', 'vrije mededeling']) {
  if (col(name) < 0) throw new Error(`This does not look like a KBC export: the column "${name}" is missing`);
}
const num = (s) => Number(String(s ?? '').trim().replace(/\./g, '').replace(',', '.'));
const date = (s) => {
  const [d, m, y] = String(s).trim().split('/');
  return `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
};
const get = (cells, name) => (col(name) >= 0 ? (cells[col(name)] ?? '').trim() : '');

const rows = lines.slice(1).map((line, i) => {
  const cells = line.split(';');
  return {
    booked_on: date(get(cells, 'datum')),
    amount: num(get(cells, 'bedrag')),
    currency: get(cells, 'munt') || 'EUR',
    name: get(cells, 'naam tegenpartij'),
    iban: get(cells, 'rekening tegenpartij').replace(/\s/g, ''),
    message: get(cells, 'vrije mededeling'),
    balance: get(cells, 'saldo') ? num(get(cells, 'saldo')) : null,
    file: fileName,
    line: i + 2, // line number in the file: importing the same file twice changes nothing
  };
});
return [{ json: { fileName, lineCount: rows.length, rows } }];

