// Match each new incoming payment to an open invoice. The rules, from sure to less sure:
//   1. structured reference (+++123/4567/89012+++)        -> matched
//   2. invoice number typed in the message (2026-0285)    -> matched
//   3. same amount and the same name as on the invoice    -> matched if only one invoice fits
//   anything else                                          -> a person checks it (with a suggestion when there is one)
const lines = $('Save the bank lines').all().map((i) => i.json).filter((l) => l.id);
const open = $input.all().map((i) => i.json).filter((i) => i.id);

const digits = (s) => String(s ?? '').replace(/\D/g, '');
const byOgm = new Map(open.filter((i) => i.ogm).map((i) => [digits(i.ogm), i]));
const byNumber = new Map(open.map((i) => [i.number, i]));
const words = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
  .replace(/[^a-z]+/g, ' ').split(' ').filter((w) => w.length > 1);
const sameName = (a, b) => {
  const wa = new Set(words(a));
  const wb = words(b);
  const common = wb.filter((w) => wa.has(w)).length;
  return common >= 2 || (common >= 1 && Math.min(wa.size, wb.length) === 1);
};
const left = (i) => Math.round((Number(i.total) - Number(i.paid_amount)) * 100) / 100;

const matches = [];
let ignored = 0;
for (const line of lines) {
  const amount = Number(line.amount);
  if (!(amount > 0)) { ignored += 1; continue; } // money going out is not a customer payment

  const msg = String(line.message ?? '');
  const ogm = msg.match(/\+{3}\s*(\d{3})\s*\/?\s*(\d{4})\s*\/?\s*(\d{5})\s*\+{3}/) || msg.match(/(?<!\d)(\d{12})(?!\d)/);
  const ogmInvoice = ogm && byOgm.get(digits(ogm.slice(1).join('')));
  if (ogmInvoice) {
    matches.push({ tx_id: line.id, invoice_id: ogmInvoice.id, result: 'matched', method: 'ogm', confidence: 1, invoice: ogmInvoice.number, reason: null });
    continue;
  }

  const nr = msg.match(/(20\d{2})\s*[-\/ ]?\s*(\d{4})(?!\d)/);
  const nrInvoice = nr && byNumber.get(`${nr[1]}-${nr[2]}`);
  if (nrInvoice) {
    matches.push({ tx_id: line.id, invoice_id: nrInvoice.id, result: 'matched', method: 'invoice_number', confidence: 0.9, invoice: nrInvoice.number, reason: null });
    continue;
  }

  const sameAmount = open.filter((i) => left(i) === amount);
  const named = sameAmount.filter((i) => sameName(i.customer_name, line.counterparty_name));
  if (named.length === 1) {
    matches.push({ tx_id: line.id, invoice_id: named[0].id, result: 'matched', method: 'amount_name', confidence: 0.75, invoice: named[0].number, reason: null });
    continue;
  }

  const guess = named[0] ?? (sameAmount.length === 1 ? sameAmount[0] : null);
  matches.push({
    tx_id: line.id,
    invoice_id: guess ? guess.id : null,
    result: 'check',
    method: guess ? 'suggestion' : null,
    confidence: guess ? 0.4 : 0,
    invoice: guess ? guess.number : null,
    reason: guess
      ? `No reference. Same amount as invoice ${guess.number}; please confirm.`
      : `No invoice found for ${amount.toFixed(2)} from ${line.counterparty_name || 'unknown'} ("${msg}")`,
  });
}

return [{ json: { matches, newLines: lines.length, ignored } }];

