// What happened, for the person who uploaded the file and for the team.
const read = $('Read the bank file').first().json;
const m = $('Match each payment').first().json;
const done = $('Register the payments').all().map((i) => i.json).filter((r) => r.invoice_number);

const count = (fn) => done.filter(fn).length;
const checks = m.matches.filter((x) => x.result === 'check');
const partly = done.filter((r) => r.result === 'partly_paid');
const lines = [
  `File: ${read.fileName} (${read.lineCount} lines)`,
  `Imported before, skipped: ${read.lineCount - m.newLines}`,
  `Outgoing payments, ignored: ${m.ignored}`,
  `Invoices paid, access given: ${count((r) => r.result === 'paid' || r.result === 'paid_too_much')} (new accounts: ${count((r) => r.new_account)})`,
  `Paid only partly: ${partly.length}`,
  `For a person to check: ${checks.length}`,
];
const forTeam = [
  ...partly.map((r) => `Invoice ${r.invoice_number}: paid ${r.paid} of ${r.total}`),
  ...checks.map((c) => c.reason),
];
return [{ json: { summary: lines.join('\n'), needsPerson: forTeam.length > 0, forTeam } }];
